  depends_on linux: :any

  binary "artcraft-launcher-#{version}-linux-#{arch}/bin/artcraft-launcher"
  # Why upstream's reverse-DNS file names are kept: on Wayland the compositor
  # finds a window's launcher, and so its dock icon, by matching the window's
  # app_id against the installed .desktop file's name.
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/applications/ai.storyteller.artcraft-launcher.desktop",
           target: "#{Dir.home}/.local/share/applications/ai.storyteller.artcraft-launcher.desktop"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/128x128/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/128x128/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/16x16/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/16x16/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/24x24/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/24x24/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/256x256/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/256x256/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/32x32/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/32x32/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/48x48/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/48x48/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/512x512/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/512x512/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/64x64/apps/ai.storyteller.artcraft-launcher.png",
           target: "#{Dir.home}/.local/share/icons/hicolor/64x64/apps/ai.storyteller.artcraft-launcher.png"
  artifact "artcraft-launcher-#{version}-linux-#{arch}/share/icons/hicolor/scalable/apps/ai.storyteller.artcraft-launcher.svg",
           target: "#{Dir.home}/.local/share/icons/hicolor/scalable/apps/ai.storyteller.artcraft-launcher.svg"

  preflight_steps do
    # Why: upstream's entry runs the bare binary name and relies on the
    # session's PATH, which on a desktop usually lacks the Homebrew prefix — only
    # login shells that source brew's shellenv have it. Pointing Exec at the bin symlink keeps the
    # entry working across upgrades and keeps upstream's own arguments (%F).
    # No `audit_result: false`: an entry with no Exec line is a broken payload.
    inreplace "artcraft-launcher-{{version}}-linux-{{arch}}/share/applications/" \
              "ai.storyteller.artcraft-launcher.desktop",
              /^Exec=\S+/,
              "Exec={{HOMEBREW_PREFIX}}/bin/artcraft-launcher"
    # Why TryExec too: a TryExec the shell cannot resolve hides the entry
    # outright, so leaving it bare would undo the Exec fix above. Not every app
    # sets one, hence `audit_result: false`.
    inreplace "artcraft-launcher-{{version}}-linux-{{arch}}/share/applications/" \
              "ai.storyteller.artcraft-launcher.desktop",
              /^TryExec=.*$/,
              "TryExec={{HOMEBREW_PREFIX}}/bin/artcraft-launcher",
              audit_result: false
  end

  # Why: without a refresh the launcher, its icon and the file associations only
  # appear after the next login. `must_succeed: false` keeps each step a no-op
  # on desktops that do not ship the tool.
  #
  # The paths are spelled out with `{{user}}` rather than `~` because these
  # steps run in Homebrew's cask sandbox, whose $HOME is an empty directory, and
  # `writable_paths` with `writable_base: :home` is what lets them write to the
  # real one. This is the same pattern every other desktop cask in this tap
  # uses; see paseo-linux.rb for the long version.
  postflight_steps do
    run "update-desktop-database",
        args:           ["."],
        chdir:          "/home/{{user}}/.local/share/applications",
        writable_paths: [".local/share/applications"],
        writable_base:  :home,
        must_succeed:   false
    run "gtk-update-icon-cache",
        args:           ["-f", "-t", "."],
        chdir:          "/home/{{user}}/.local/share/icons/hicolor",
        writable_paths: [".local/share/icons/hicolor"],
        writable_base:  :home,
        must_succeed:   false
    run "update-mime-database",
        args:           ["."],
        chdir:          "/home/{{user}}/.local/share/mime",
        writable_paths: [".local/share/mime"],
        writable_base:  :home,
        must_succeed:   false
  end

  uninstall_postflight_steps do
    run "update-desktop-database",
        args:           ["."],
        chdir:          "/home/{{user}}/.local/share/applications",
        writable_paths: [".local/share/applications"],
        writable_base:  :home,
        must_succeed:   false
    run "gtk-update-icon-cache",
        args:           ["-f", "-t", "."],
        chdir:          "/home/{{user}}/.local/share/icons/hicolor",
        writable_paths: [".local/share/icons/hicolor"],
        writable_base:  :home,
        must_succeed:   false
    run "update-mime-database",
        args:           ["."],
        chdir:          "/home/{{user}}/.local/share/mime",
        writable_paths: [".local/share/mime"],
        writable_base:  :home,
        must_succeed:   false
  end

  zap trash: [
    "~/.cache/artcraft-launcher",
    "~/.config/autostart/ai.storyteller.artcraft-launcher.desktop",
    "~/.local/share/ai.storyteller.artcraft-launcher",
    "~/.local/share/artcraft-launcher",
